 using C=StartupConfigCopyTask;using Q=StartupQueueClearTask;using O=StartupStateCallTask;using B=StartupBoundsTask;using G=StartupGlyphTask;struct Job{std::variant<C,Q,O,B,G>task;uint16_t pattern=0;};
public:
 enum class Kind:uint8_t{ConfigCopy,QueueClear,EncoderInitialize,ConfigLoad,BoundsCheck,Glyphs};enum class Block:uint8_t{None,NotBound,Inactive,NeedsInterrupt,UnsupportedMode,LcdBusy};struct Result{unsigned clocks=0;bool returned=false;Block blocked=Block::None;};struct Range{uint32_t begin,end;};inline static constexpr std::array<Range,7>CodeRanges{{{0x1434,0x1442},{0x1454,0x1456},{0x1bc6,0x1bd0},{0x1e1c,0x1e30},{0x1ea4,0x1eb2},{0x2036,0x2062},{0x23c2,0x23f8}}};
 bool bindBootResources(ControllerDeviceState&d,const uint8_t*image,size_t size){if(bound_||active()||!image||size!=49728||!d.hasImmutableCapacity(CodeRanges.size()))return false;for(auto r:CodeRanges)for(auto a=r.begin;a<r.end;++a)if(d.readResource(a)!=image[a])return false;for(auto r:CodeRanges)if(!d.protectImmutableVerified(r.begin,r.end,image+r.begin))return false;bound_=&d;return true;}
 bool bindMirroredFirmware(ControllerDeviceState&d,const uint8_t*image,size_t size){if(bound_!=&d||mirrored_||!image||size!=49728||!d.hasImmutableCapacity(CodeRanges.size()))return false;for(auto r:CodeRanges)for(auto a=r.begin;a<r.end;++a)if(d.readResource(a)!=image[a]||d.readResource(0x400000+a)!=image[a])return false;for(auto r:CodeRanges)if(!d.protectImmutableVerified(0x400000+r.begin,0x400000+r.end,image+r.begin))return false;mirrored_=true;return true;}
 bool boundTo(const ControllerDeviceState&d)const{return bound_==&d;}bool active()const{return depth_!=0;}void reset(){depth_=0;lcdChild_=false;}
 bool start(Kind kind){if(!bound_||active())return false;auto&j=jobs_[depth_++];j.pattern=0;switch(kind){case Kind::ConfigCopy:j.task.emplace<C>();break;case Kind::QueueClear:j.task.emplace<Q>();break;case Kind::EncoderInitialize:j.task.emplace<O>(O::Kind::Queue);break;case Kind::ConfigLoad:j.task.emplace<O>(O::Kind::Config);break;case Kind::BoundsCheck:j.task.emplace<B>();break;case Kind::Glyphs:j.task.emplace<G>();break;}return true;}
 unsigned nextClocks(const ControllerDeviceState&d,const ControllerInterruptRuntime&irq,const ControllerLcdRuntime&lcd)const{if(bound_!=&d||!active()||!lcd.boundTo(d)||d.interruptMode2||d.pendingIrqsHigh||irq.active()||(!irq.boundTo(d)&&irq.mask()!=ControllerInterruptRuntime::Mask::Disabled)||(d.pendingIrqs&&irq.mask()==ControllerInterruptRuntime::Mask::Enabled))return 0;if(lcdChild_)return lcd.nextClocks(d,irq);if(glyphCall(jobs_[depth_-1])&&lcd.active())return 0;auto cr=credits(d);auto n=std::visit([&](const auto&t){return t.nextClocks(cr);},jobs_[depth_-1].task);return n?n+(d.pendingIrqs?1u:0u):0;}
 Result advanceBefore(ControllerDeviceState&d,ControllerInterruptRuntime&irq,ControllerLcdRuntime&lcd,unsigned available){if(bound_!=&d||!lcd.boundTo(d))return {0,false,Block::NotBound};if(!active())return {0,false,Block::Inactive};if(d.interruptMode2||d.pendingIrqsHigh)return {0,false,Block::UnsupportedMode};if(irq.active()||(!irq.boundTo(d)&&irq.mask()!=ControllerInterruptRuntime::Mask::Disabled)||(d.pendingIrqs&&irq.mask()==ControllerInterruptRuntime::Mask::Enabled))return {0,false,Block::NeedsInterrupt};if(lcdChild_){auto r=lcd.advanceBefore(d,irq,available);if(r.returned){lcdChild_=false;std::get<G>(jobs_[depth_-1].task).resume();}return {r.clocks,false,Block::None};}if(glyphCall(jobs_[depth_-1])&&lcd.active())return {0,false,Block::LcdBusy};auto total=nextClocks(d,irq,lcd);if(!total||available<total)return {};auto arb=d.pendingIrqs?1u:0u;if(arb)(void)d.read8(0xfffff2);auto clocks=total-arb;auto begin=d.cycles;auto&j=jobs_[depth_-1];auto cr=credits(d);bool stack=false,done=false,child=false,config=false,lcdCall=false;auto lcdKind=LcdTextTask::Kind::DirectData;uint8_t value=0;
 std::visit([&](auto&t){using X=std::decay_t<decltype(t)>;if constexpr(std::is_same_v<X,C>){check(t.advanceBefore(clocks,cr,[&](unsigned index){d.cycles=begin+3;return d.read8(0x21fd00+index);},[&](unsigned index,unsigned v){d.cycles=begin+(index<256?3u:9u);write(d,0xc8ae + index,index<256?1:2,v);})==clocks);}else if constexpr(std::is_same_v<X,Q>){stack=t.stage()==Q::Stage::Retain;check(t.advanceBefore(clocks,cr,[&](bool producer,unsigned v){d.cycles=begin+9;write(d,producer?0xc6aa:0xc6ac,2,v);})==clocks);}else if constexpr(std::is_same_v<X,O>){child=t.stage()==O::Stage::Call;config=t.kind()==O::Kind::Config;stack=child;check(t.advanceBefore(clocks,cr,[&](unsigned v){d.cycles=begin+(config?9u:3u);d.write8(config?0xc9b2:0xffffd6,uint8_t(v));})==clocks);}else if constexpr(std::is_same_v<X,B>){check(t.advanceBefore(clocks,cr)==clocks);}else{using S=G::Stage;auto stage=t.stage();lcdCall=glyphCall(j);stack=lcdCall;if(stage==S::Pattern)j.pattern=0x3e0;if(stage==S::Shift)j.pattern>>=1;if(stage==S::Cgram)lcdKind=LcdTextTask::Kind::Cgram;value=stage==S::WritePattern?uint8_t(j.pattern):stage==S::WriteBottom?31:stage==S::WriteFinal?16:0;check(t.advanceBefore(clocks,cr)==clocks);}done=t.complete();},j.task);
 d.cycles=begin+clocks;d.lastRead=-1;if(stack)d.lastWrite=-1;if(child){if(depth_==jobs_.size())throw std::logic_error("K startup state capacity");auto&next=jobs_[depth_++];if(config)next.task.emplace<C>();else next.task.emplace<Q>();}else if(lcdCall){if(!lcd.start(lcdKind,value))throw std::logic_error("K startup glyph LCD admission");lcdChild_=true;}else if(done){--depth_;if(depth_)std::get<O>(jobs_[depth_-1].task).resume();}return {total,depth_==0,Block::None};}
private:static void check(bool p){if(!p)throw std::logic_error("K domain startup state phase");}static void write(ControllerDeviceState&d,unsigned a,unsigned width,unsigned value){for(unsigned i=0;i<width;++i)d.write8(a+i,uint8_t(value>>(8*(width-i-1))));}static bool glyphCall(const Job&j){auto*t=std::get_if<G>(&j.task);if(!t)return false;auto s=t->stage();return s==G::Stage::Cgram||s==G::Stage::WritePattern||s==G::Stage::WriteClear||s==G::Stage::WriteBottom||s==G::Stage::WriteFinal;}static unsigned bus(unsigned a,unsigned width,int last){unsigned n=0;for(unsigned i=0;i<width;++i){auto p=(a+i)&0xffffff;if(p<0x400000||(p>=0xfffd10&&p<0xffffa0)){if((last&1)||p!=unsigned(last|1))n+=p<0x400000?3:1;last=int(p);}else{n+=p>=0xffffa0?1:3;last=-1;}}return n;}
 FlashCredits credits(const ControllerDeviceState&d)const{FlashCredits cr;cr.pushWord=cr.popWord=6;cr.call=10;cr.shortCall=5;cr.ret=7;cr.read=3;const auto&j=jobs_[depth_-1];if(auto*t=std::get_if<C>(&j.task))cr.write=t->stage()==C::Stage::WriteFirst?bus(0xc9ae,2,d.lastWrite):t->stage()==C::Stage::WriteSecond?bus(0xc9b0,2,d.lastWrite):bus(0xc8ae + t->index(),1,d.lastWrite);else if(auto*t=std::get_if<Q>(&j.task))cr.write=bus(t->stage()==Q::Stage::WriteProducer?0xc6aa:0xc6ac,2,d.lastWrite);else if(auto*t=std::get_if<O>(&j.task))cr.write=bus(t->kind()==O::Kind::Queue?0xffffd6:0xc9b2,1,d.lastWrite);return cr;}
 ControllerDeviceState*bound_=nullptr;bool mirrored_=false;std::array<Job,2>jobs_{};unsigned depth_=0;bool lcdChild_=false;
